-- Verify CPF R6 V106 persistent data-quality provider schema
DELIMITER $$
DROP PROCEDURE IF EXISTS CPF_VERIFY_DQ_V106$$
CREATE PROCEDURE CPF_VERIFY_DQ_V106()
BEGIN
  DECLARE v_count INT DEFAULT 0;
  SELECT COUNT(*) INTO v_count FROM information_schema.columns WHERE table_schema=DATABASE() AND upper(table_name)='CPF_DATA_QUALITY_RULE' AND upper(column_name)='PARAMETERS_PAYLOAD';
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PARAMETERS_PAYLOAD missing'; END IF;
  SELECT COUNT(*) INTO v_count FROM information_schema.columns WHERE table_schema=DATABASE() AND upper(table_name)='CPF_DATA_QUALITY_QUARANTINE' AND upper(column_name)='VIOLATION_PAYLOAD';
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='VIOLATION_PAYLOAD missing'; END IF;
  SELECT COUNT(*) INTO v_count FROM information_schema.tables WHERE table_schema=DATABASE() AND upper(table_name)='CPF_DATA_QUALITY_OPERATION';
  IF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='CPF_DATA_QUALITY_OPERATION missing'; END IF;
END$$
CALL CPF_VERIFY_DQ_V106()$$
DROP PROCEDURE CPF_VERIFY_DQ_V106$$
DELIMITER ;
SELECT COUNT(*) AS persistent_dq_operations FROM CPF_DATA_QUALITY_OPERATION;
